// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Phishable} from "../src/Phishable.sol";

contract InvMutTest is Test {
    Phishable c;
    function setUp() public { c = new Phishable(address(this)); }
    function testFuzz_property(address owner, uint256 amount, address recipient) public {
        vm.assume(owner != address(0));
        vm.assume(recipient != address(0));
        vm.assume(amount > 0);
        vm.assume(owner != address(c));

        Phishable fuzzedC = new Phishable(owner);
        vm.deal(address(fuzzedC), amount);
        assertEq(address(fuzzedC).balance, amount, "setup balance");

        vm.prank(owner);
        fuzzedC.withdrawAll(recipient);

        assertEq(address(fuzzedC).balance, 0, "owner must be able to drain all funds");
    }
}
